package main
import "fmt"
func main() {
    var x int
    fmt.Scanln(&x)
    t := Timer{"timer1", 0}
    for i:=0;i<x;i++ {
        t.tick()
    }
}
type Timer struct{
	id string
	value int
}
func(t * Timer) tick(){
    t.value = t.value+1
    fmt.Println(t.value)
}
